package com.smartmerchant.saas.member.application;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.sql.Timestamp;import java.time.LocalDateTime;import java.util.*;
@Component public class AnalyticsOutbox {private final JdbcTemplate jdbc;private final ObjectMapper json;private final RestClient analytics;private final String key;public AnalyticsOutbox(JdbcTemplate j,ObjectMapper o,@Value("${saas.member.analytics-service-url:http://localhost:8083}")String url,@Value("${saas.security.internal-signing-key}")String key){jdbc=j;json=o;analytics=RestClient.builder().baseUrl(url).build();this.key=key;}public void event(long t,String type,long aggregate,Map<String,Object> p){try{jdbc.update("INSERT INTO analytics_outbox(event_id,tenant_id,event_type,aggregate_id,occurred_at,payload_json) VALUES (?,?,?,?,?,?)",UUID.randomUUID().toString(),t,type,String.valueOf(aggregate),LocalDateTime.now(),json.writeValueAsString(p));}catch(Exception e){throw new IllegalStateException("Cannot persist analytics outbox",e);}}@Scheduled(fixedDelayString="${saas.member.analytics-outbox-delay-ms:5000}")public void publish(){for(var r:jdbc.queryForList("SELECT * FROM analytics_outbox WHERE published_at IS NULL ORDER BY created_at LIMIT 100")){String id=s(r,"EVENT_ID");try{var p=json.readValue(s(r,"PAYLOAD_JSON"),new TypeReference<Map<String,Object>>(){});analytics.post().uri("/internal/v1/analytics/events").header("X-Internal-Key",key).body(Map.of("eventId",id,"eventType",s(r,"EVENT_TYPE"),"eventVersion",1,"tenantId",n(r,"TENANT_ID"),"aggregateId",s(r,"AGGREGATE_ID"),"occurredAt",((Timestamp)r.get("OCCURRED_AT")).toInstant().toString(),"payload",p)).retrieve().toBodilessEntity();jdbc.update("UPDATE analytics_outbox SET published_at=CURRENT_TIMESTAMP,last_error=NULL WHERE event_id=?",id);}catch(Exception e){String m=String.valueOf(e.getMessage());jdbc.update("UPDATE analytics_outbox SET attempts=attempts+1,last_error=? WHERE event_id=?",m.substring(0,Math.min(500,m.length())),id);}}}private static long n(Map<String,Object>r,String k){Object x=r.get(k);if(x==null)x=r.get(k.toLowerCase());return((Number)x).longValue();}private static String s(Map<String,Object>r,String k){Object x=r.get(k);if(x==null)x=r.get(k.toLowerCase());return String.valueOf(x);}}
